import * as THREE from "three";
import build from "../../samples/ancientTreant";

const root = build();
const box = new THREE.Box3().setFromObject(root, true);
console.log("size", box.getSize(new THREE.Vector3()).toArray().map((v) => v.toFixed(2)), "min", box.min.toArray().map((v) => v.toFixed(3)), "max", box.max.toArray().map((v) => v.toFixed(3)));
let meshes = 0;
let tris = 0;
const colors = new Set<string>();
let joints = 0;
root.traverse((o) => {
  if ((o as THREE.Mesh).isMesh) {
    const m = o as THREE.Mesh;
    meshes++;
    const g = m.geometry;
    tris += g.index ? g.index.count / 3 : g.attributes.position.count / 3;
    const mat = m.material as THREE.MeshStandardMaterial;
    if (!mat.map) colors.add(mat.color.getHexString());
  }
  if (o.type === "Group" || o.type === "Bone") joints++;
});
console.log({ meshes, tris, colors: colors.size, joints });
